543	// FindingChange pairs the archived and compared conclusions for one
544	// transaction whose kind or severity differs between the two versions.
545	type FindingChange struct {
546		TxHash   string        `json:"txHash"`
547		Original ReportFinding `json:"original"`
548		Compared ReportFinding `json:"compared"`
549	}
550	
551	// CompareResult is the outcome of re-judging one archived block under a
552	// different rule version. It carries both versions' parameters, both full
553	// conclusion sets, the raw swap evidence, and the per-transaction diff.
554	type CompareResult struct {
555		ChainID          string          `json:"chainId"`
556		BlockHash        string          `json:"blockHash"`
557		BlockNumber      int64           `json:"blockNumber"`
558		OriginalVersion  RuleVersion     `json:"originalVersion"`
559		ComparedVersion  RuleVersion     `json:"comparedVersion"`
560		OriginalFindings []ReportFinding `json:"originalFindings"`
561		ComparedFindings []ReportFinding `json:"comparedFindings"`
562		Swaps            []Swap          `json:"swaps"`
563		Added            []ReportFinding `json:"added"`
564		Removed          []ReportFinding `json:"removed"`
565		Changed          []FindingChange `json:"changed"`
566	}
567	
568	// rawVersionArchiveDoc mirrors the archive file the way a comparison and a
569	// review-range evaluation read it: records and reviews are fully decoded,
570	// but each registered version is kept as its raw stored document. A corrupt
571	// version entry — a wrong-typed field, say — then cannot break the read or
572	// masquerade as whole-archive corruption; it is judged on its own by
573	// intactVersion, so a corrupt sibling never contaminates an intact
574	// candidate or the built-in version.
575	type rawVersionArchiveDoc struct {
576		Records  []record          `json:"records"`
577		Versions []json.RawMessage `json:"versions"`
578		Reviews  []ReviewObject    `json:"reviews"`
579	}
580	
581	// Compare re-runs detection for one archived block under the given
582	// registered version and diffs the conclusions against the archived
583	// report. It only reads the archive: the original input file is not
584	// needed, and neither the archived report nor the enabled version is
585	// modified. The named version's stored document must still satisfy the
586	// registration rules in full; a corrupt one fails with ErrCorruptVersion
587	// rather than comparing under zeroed or substituted parameters.
588	func Compare(dir, chainID, blockHash, versionID string) (CompareResult, error) {
589		if _, err := os.Stat(dir); err != nil {
590			if errors.Is(err, os.ErrNotExist) {
591				return CompareResult{}, ErrUnknownBlock
592			}
593			return CompareResult{}, err
594		}
595		lock, err := lockArchive(dir, syscall.LOCK_SH)
596		if err != nil {
597			return CompareResult{}, err
598		}
599		defer lock.Close()
600	
601		raw, err := readArchiveBytes(dir)
602		if err != nil {
603			return CompareResult{}, err
604		}
605		var doc rawVersionArchiveDoc
606		if len(raw) > 0 {
607			if err := json.Unmarshal(raw, &doc); err != nil {
608				return CompareResult{}, fmt.Errorf("archive is corrupted: %w", err)
609			}
610		}
611		var rec *record
612		for i := range doc.Records {
613			if doc.Records[i].ChainID == chainID && doc.Records[i].BlockHash == blockHash {
614				rec = &doc.Records[i]
615				break
616			}
617		}
618		if rec == nil {
619			return CompareResult{}, ErrUnknownBlock
620		}
621		// The requested version must be intact in the archive: re-validate its
622		// stored document before judging anything, so a corrupt version fails
623		// the same way even when the block has no swaps and detection would
624		// produce no conclusions at all.
625		compared, err := intactVersion(doc.Versions, versionID)
626		if err != nil {
627			return CompareResult{}, err
628		}
629		original := rec.Findings
630		if original == nil {
631			original = []ReportFinding{}
632		}
633		rejudged := DetectBlockWithRules(rec.Swaps, compared.Rules)
634		swaps := rec.Swaps
635		if swaps == nil {
636			swaps = []Swap{}
637		}
638	
639		origByTx := make(map[string]ReportFinding, len(original))
640		for _, f := range original {
641			origByTx[f.TxHash] = f
642		}
643		compByTx := make(map[string]ReportFinding, len(rejudged))
644		for _, f := range rejudged {
645			compByTx[f.TxHash] = f
646		}
647		added := []ReportFinding{}
648		removed := []ReportFinding{}
649		changed := []FindingChange{}
650		for _, f := range rejudged {
651			if o, ok := origByTx[f.TxHash]; ok {
652				// A transaction present on both sides with a different kind or
653				// severity is a change, never an add plus a remove.
654				if o.Kind != f.Kind || o.Severity != f.Severity {
655					changed = append(changed, FindingChange{TxHash: f.TxHash, Original: o, Compared: f})
656				}
657			} else {
658				added = append(added, f)
659			}
660		}
661		for _, f := range original {
662			if _, ok := compByTx[f.TxHash]; !ok {
663				removed = append(removed, f)
664			}
665		}
666		byTx := func(fs []ReportFinding) {
667			sort.Slice(fs, func(i, j int) bool { return fs[i].TxHash < fs[j].TxHash })
668		}
669		byTx(added)
670		byTx(removed)
671		sort.Slice(changed, func(i, j int) bool { return changed[i].TxHash < changed[j].TxHash })
672	
673		return CompareResult{
674			ChainID:          rec.ChainID,
675			BlockHash:        rec.BlockHash,
676			BlockNumber:      rec.BlockNumber,
677			OriginalVersion:  rec.ruleVersion(),
678			ComparedVersion:  compared,
679			OriginalFindings: original,
680			ComparedFindings: rejudged,
681			Swaps:            swaps,
682			Added:            added,
683			Removed:          removed,
684			Changed:          changed,
685		}, nil
686	}
687

