1	package mevwatch
2	
3	// Regression coverage for enabling a rule version whose stored archive
4	// document has decayed since registration. `rules enable` must validate the
5	// selected version's actual stored declaration before it moves the enabled
6	// marker — the same proof a comparison, a review-range evaluation and a
7	// replay already demand — so a corrupt registered version is refused with
8	// ErrCorruptVersion (never reported unknown, never substituted with the
9	// current, built-in or default parameters), even when it is already the
10	// enabled version. A successful switch changes only the enabled marker:
11	// the other versions (corrupt siblings included), their fields and order,
12	// plus reports, suppressions, alert records and reviews are preserved.
13	
14	import (
15		"encoding/json"
16		"errors"
17		"os"
18		"path/filepath"
19		"reflect"
20		"strings"
21		"syscall"
22		"testing"
23	)
24	
25	// enableSkeleton reads the archive the way EnableVersion writes it:
26	// versions stay raw stored documents, so the sections can be compared
27	// byte for byte across a successful switch.
28	type enableSkeleton struct {
29		Records        []record           `json:"records"`
30		Versions       []json.RawMessage  `json:"versions"`
31		EnabledVersion string             `json:"enabledVersion"`
32		Suppressions   []Suppression      `json:"suppressions"`
33		AlertRecords   []ProcessingRecord `json:"alerts"`
34		Reviews        []ReviewObject     `json:"reviews"`
35	}
36	
37	func readEnableSkeleton(t *testing.T, dir string) enableSkeleton {
38		t.Helper()
39		var s enableSkeleton
40		if err := json.Unmarshal(readArchiveFile(t, dir), &s); err != nil {
41			t.Fatal(err)
42		}
43		return s
44	}
45	
46	// TestEnableCorruptVersionRefused runs the full corruption matrix against
47	// enabling a registered version: every way its stored document can stop
48	// satisfying the registration rules must fail with ErrCorruptVersion, name
49	// the version and the offending rule or field, and leave the archive —
50	// including the enabled marker — untouched.
51	func TestEnableCorruptVersionRefused(t *testing.T) {
52		for _, tc := range corruptVersionCases {
53			t.Run(tc.name, func(t *testing.T) {
54				dir := setupCorruptCompareArchive(t)
55				if _, err := EnableVersion(dir, "twin"); err != nil {
56					t.Fatalf("setup: EnableVersion twin: %v", err)
57				}
58				rewriteStoredVersion(t, dir, "candC", func(ver map[string]any) {
59					tc.mutate(t, ver)
60				})
61				before := readArchiveFile(t, dir)
62	
63				v, err := EnableVersion(dir, "candC")
64				if err == nil {
65					t.Fatalf("corrupt version enabled successfully: %+v", v)
66				}
67				if !errors.Is(err, ErrCorruptVersion) {
68					t.Fatalf("error = %v, want ErrCorruptVersion", err)
69				}
70				if errors.Is(err, ErrUnknownVersion) {
71					t.Fatalf("registered-but-corrupt version misreported as unknown: %v", err)
72				}
73				if !strings.Contains(err.Error(), "candC") {
74					t.Fatalf("error must name the selected version, got %v", err)
75				}
76				if !strings.Contains(err.Error(), tc.wantErr) {
77					t.Fatalf("error must name the offending rule or field %q, got %v", tc.wantErr, err)
78				}
79				if after := readArchiveFile(t, dir); !reflect.DeepEqual(before, after) {
80					t.Fatalf("refused enable changed the archive:\nbefore=%s\nafter =%s", before, after)
81				}
82				if got := readEnableSkeleton(t, dir).EnabledVersion; got != "twin" {
83					t.Fatalf("enabled marker changed to %q on refusal", got)
84				}
85			})
86		}
87	}
88	
89	// TestEnableCorruptAlreadyEnabledRefused pins the core regression: the
90	// integrity check runs even when the selected id is already the current
91	// enabled version. Previously the early return accepted the decayed
92	// document as a complete version and left replay to fail later.
93	func TestEnableCorruptAlreadyEnabledRefused(t *testing.T) {
94		for _, tc := range corruptVersionCases {
95			t.Run(tc.name, func(t *testing.T) {
96				dir := setupCorruptCompareArchive(t)
97				if _, err := EnableVersion(dir, "candC"); err != nil {
98					t.Fatalf("setup: EnableVersion candC: %v", err)
99				}
100				rewriteStoredVersion(t, dir, "candC", func(ver map[string]any) {
101					tc.mutate(t, ver)
102				})
103				before := readArchiveFile(t, dir)
104	
105				v, err := EnableVersion(dir, "candC")
106				if !errors.Is(err, ErrCorruptVersion) {
107					t.Fatalf("re-enabling the corrupt enabled version: v=%+v err=%v, want ErrCorruptVersion", v, err)
108				}
109				if errors.Is(err, ErrUnknownVersion) {
110					t.Fatalf("corrupt enabled version misreported as unknown: %v", err)
111				}
112				if !strings.Contains(err.Error(), "candC") || !strings.Contains(err.Error(), tc.wantErr) {
113					t.Fatalf("error must name version candC and field %q, got %v", tc.wantErr, err)
114				}
115				if after := readArchiveFile(t, dir); !reflect.DeepEqual(before, after) {
116					t.Fatalf("refused re-enable changed the archive")
117				}
118				if got := readEnableSkeleton(t, dir).EnabledVersion; got != "candC" {
119					t.Fatalf("enabled marker changed on refusal: %q", got)
120				}
121			})
122		}
123	}
124	
125	// TestEnableCorruptSiblingDoesNotBlock proves damage in one registered
126	// version neither blocks enabling an intact sibling or builtin, nor gets
127	// repaired, completed, reordered or dropped by the successful switch: the
128	// versions section survives entry for entry, in order, and the corrupt
129	// entry is still afterwards refused on its own merits.
130	func TestEnableCorruptSiblingDoesNotBlock(t *testing.T) {
131		dir := setupCorruptCompareArchive(t)
132		before := readEnableSkeleton(t, dir)
133		rewriteStoredVersion(t, dir, "candC", func(ver map[string]any) {
134			storedRule(t, ver, "displacement")["multiplier"] = 0
135		})
136		damaged := readEnableSkeleton(t, dir)
137	
138		twin, err := EnableVersion(dir, "twin")
139		if err != nil {
140			t.Fatalf("enabling intact twin past a corrupt sibling failed: %v", err)
141		}
142		if twin.ID != "twin" || twin.Rules.Displacement.Multiplier != 2 {
143			t.Fatalf("enabled twin returned wrong parameters: %+v", twin)
144		}
145		after := readEnableSkeleton(t, dir)
146		if !reflect.DeepEqual(damaged.Versions, after.Versions) {
147			t.Fatalf("successful switch rewrote the versions section:\nbefore=%s\nafter =%s", damaged.Versions, after.Versions)
148		}
149		if after.EnabledVersion != "twin" {
150			t.Fatalf("enabled marker = %q, want twin", after.EnabledVersion)
151		}
152	
153		// Builtin needs no registration and is enableable with the same corrupt
154		// sibling present; its original parameters come back in full.
155		b, err := EnableVersion(dir, BuiltinVersionID)
156		if err != nil {
157			t.Fatalf("enabling builtin past a corrupt sibling failed: %v", err)
158		}
159		if b != BuiltinVersion() {
160			t.Fatalf("builtin parameters wrong: %+v", b)
161		}
162		after = readEnableSkeleton(t, dir)
163		if !reflect.DeepEqual(damaged.Versions, after.Versions) {
164			t.Fatalf("enabling builtin rewrote the versions section")
165		}
166		if after.EnabledVersion != BuiltinVersionID {
167			t.Fatalf("enabled marker = %q, want builtin", after.EnabledVersion)
168		}
169	
170		// The corrupt entry was not repaired: selecting it still fails as
171		// corruption, and the intact twin remains usable.
172		if _, err := EnableVersion(dir, "candC"); !errors.Is(err, ErrCorruptVersion) {
173			t.Fatalf("corrupt sibling was silently repaired: %v", err)
174		}
175		if _, err := EnableVersion(dir, "twin"); err != nil {
176			t.Fatalf("intact twin no longer enableable: %v", err)
177		}
178		// Nothing structural besides the marker ever moved: order and records.
179		if len(after.Versions) != len(before.Versions) {
180			t.Fatalf("version count changed: %d vs %d", len(after.Versions), len(before.Versions))
181		}
182		if !reflect.DeepEqual(before.Records, after.Records) {
183			t.Fatalf("existing records changed on a version switch")
184		}
185	}
186	
187	// TestEnableUnknownVersionDistinct pins the boundary: an id that was never
188	// registered stays an unknown-version failure (never corruption), and the
189	// failure moves no marker.
190	func TestEnableUnknownVersionDistinct(t *testing.T) {
191		dir := setupCorruptCompareArchive(t)
192		rewriteStoredVersion(t, dir, "candC", func(ver map[string]any) {
193			delete(storedRule(t, ver, "displacement"), "multiplier")
194		})
195		before := readArchiveFile(t, dir)
196	
197		if _, err := EnableVersion(dir, "ghost"); !errors.Is(err, ErrUnknownVersion) ||
198			errors.Is(err, ErrCorruptVersion) {
199			t.Fatalf("unknown version error = %v", err)
200		}
201		if _, err := EnableVersion(dir, ""); err == nil {
202			t.Fatal("empty version id must fail")
203		}
204		if after := readArchiveFile(t, dir); !reflect.DeepEqual(before, after) {
205			t.Fatalf("failed enable changed the archive")
206		}
207		if got := readEnableSkeleton(t, dir).EnabledVersion; got != "" {
208			t.Fatalf("enabled marker changed on unknown-version failure: %q", got)
209		}
210	}
211	
212	// TestEnableExplicitlyDisabledRulesAccepted proves enabled:false is a legal
213	// off state: a version with both rules disabled still has to carry complete
214	// parameters, and enabling it returns the full declaration which then
215	// governs plain (no --version) replays.
216	func TestEnableExplicitlyDisabledRulesAccepted(t *testing.T) {
217		dir := t.TempDir()
218		offSpec := `{"id":"off","rules":{"sandwich":{"enabled":false,"severity":1},"displacement":{"enabled":false,"severity":1,"multiplier":2}}}`
219		register(t, dir, offSpec)
220		v, err := EnableVersion(dir, "off")
221		if err != nil {
222			t.Fatalf("an explicitly disabled version must enable: %v", err)
223		}
224		want := mustRuleVersion(t, offSpec)
225		if !reflect.DeepEqual(v, want) {
226			t.Fatalf("enabled version = %+v, want %+v", v, want)
227		}
228		reports := replay(t, dir, sandwichInput)
229		if len(reports[0].Findings) != 0 || reports[0].Version.ID != "off" {
230			t.Fatalf("plain replay did not use the enabled disabled version: %+v", reports[0])
231		}
232	}
