314	// TestEnableInvalidAndBusyArchiveReported covers the environment-level
315	// failures: an archive whose whole file is not valid JSON, or one locked by
316	// another process, must error clearly and leave the file alone.
317	func TestEnableInvalidAndBusyArchiveReported(t *testing.T) {
318		dir := t.TempDir()
319		register(t, dir, candidateVersionSpec)
320		path := filepath.Join(dir, archiveFileName)
321		if err := os.WriteFile(path, []byte(`{not json`), 0o644); err != nil {
322			t.Fatal(err)
323		}
324		before := readArchiveFile(t, dir)
325		if _, err := EnableVersion(dir, "candC"); err == nil ||
326			errors.Is(err, ErrUnknownVersion) || errors.Is(err, ErrCorruptVersion) {
327			t.Fatalf("invalid-JSON archive error = %v, want a whole-archive corruption error", err)
328		}
329		if after := readArchiveFile(t, dir); !reflect.DeepEqual(before, after) {
330			t.Fatalf("failed enable rewrote an invalid archive")
331		}
332	
333		// Busy archive: the lock failure is reported as such (fixture from the
334		// registration tests, version absent there so the lock is hit first).
335		busyDir := t.TempDir()
336		lock, err := os.OpenFile(filepath.Join(busyDir, lockFileName), os.O_CREATE|os.O_RDWR, 0o644)
337		if err != nil {
338			t.Fatal(err)
339		}
340		defer lock.Close()
341		if err := syscall.Flock(int(lock.Fd()), syscall.LOCK_EX); err != nil {
342			t.Fatal(err)
343		}
344		if _, err := EnableVersion(busyDir, "candC"); !errors.Is(err, ErrBusy) {
345			t.Fatalf("busy archive error = %v, want ErrBusy", err)
346		}
347	}
