349	// TestEnableLegacyArchiveAllowsBuiltin proves pre-version archives (no
350	// versions or enabledVersion fields) can still enable builtin, and the
351	// marker then drives plain replays without touching the legacy record.
352	func TestEnableLegacyArchiveAllowsBuiltin(t *testing.T) {
353		dir := t.TempDir()
354		legacy := `{"records":[{"chainId":"1","blockHash":"0old","blockNumber":5,` +
355			`"swaps":[{"TxHash":"0f","Pool":"p1","Trader":"bot","In":7,"Out":6,"GasPrice":90,"Index":0},` +
356			`{"TxHash":"0v","Pool":"p1","Trader":"user","In":5,"Out":4,"GasPrice":10,"Index":1},` +
357			`{"TxHash":"0b","Pool":"p1","Trader":"bot","In":3,"Out":5,"GasPrice":80,"Index":2}],` +
358			`"findings":[{"kind":"sandwich","severity":3,"txHash":"0v","evidence":[` +
359			`{"TxHash":"0f","Pool":"p1","Trader":"bot","In":7,"Out":6,"GasPrice":90,"Index":0},` +
360			`{"TxHash":"0v","Pool":"p1","Trader":"user","In":5,"Out":4,"GasPrice":10,"Index":1},` +
361			`{"TxHash":"0b","Pool":"p1","Trader":"bot","In":3,"Out":5,"GasPrice":80,"Index":2}]}]}]}`
362		if err := os.WriteFile(filepath.Join(dir, archiveFileName), []byte(legacy), 0o644); err != nil {
363			t.Fatal(err)
364		}
365		b, err := EnableVersion(dir, BuiltinVersionID)
366		if err != nil {
367			t.Fatalf("enabling builtin on a legacy archive failed: %v", err)
368		}
369		if b != BuiltinVersion() {
370			t.Fatalf("builtin parameters wrong: %+v", b)
371		}
372		if got := readEnableSkeleton(t, dir).EnabledVersion; got != BuiltinVersionID {
373			t.Fatalf("enabled marker = %q, want builtin", got)
374		}
375		reports := replay(t, dir, replayCorruptInput)
376		if len(reports) != 1 || reports[0].Version.ID != BuiltinVersionID ||
377			len(reports[0].Findings) != 1 || reports[0].Findings[0].Kind != "displacement" {
378			t.Fatalf("plain replay after enabling builtin misjudged: %+v", reports)
379		}
380		r, err := Query(dir, "1", "0old")
381		if err != nil {
382			t.Fatal(err)
383		}
384		if r.Version != BuiltinVersion() || len(r.Findings) != 1 {
385			t.Fatalf("legacy record modified on switch: %+v", r)
386		}
387	
388		// An empty archive (no file yet) accepts builtin the same way.
389		fresh := t.TempDir()
390		if _, err := EnableVersion(fresh, BuiltinVersionID); err != nil {
391			t.Fatalf("enabling builtin before any archive exists failed: %v", err)
392		}
393	}
